func (e Error) Error() string { return fmt.Sprintf("%s (%s %d:%d)", e.Message, e.Location.File, e.Location.Line, e.Location.Column) }

type errorsGroup []error
func (e errorsGroup) Error() string {
	if len(e) == 0 { return "" }
	return e[0].Error()
}
func (e errorsGroup) Unwrap() []error { return []error(e) }

// Unwrap extracts individual errors from a multi-error validation result.
func Unwrap(err error) ([]error, bool) {
	type multi interface { Unwrap() []error }
	var m multi
	if !errors.As(err, &m) { return nil, false }
	return m.Unwrap(), true
}

type FeaturesValidator struct { cue *cue.Context; v cue.Value }

func NewFeaturesValidator() (*FeaturesValidator, error) {
	cctx := cuecontext.New()
	v := cctx.CompileBytes(cueFile)
	if v.Err() != nil { return nil, v.Err() }
	return &FeaturesValidator{cue: cctx, v: v}, nil
}

// Validate validates a YAML file against the schema and its references.
func (v FeaturesValidator) Validate(file string, b []byte) error {
	f, err := yaml.Extract(file, b)
	if err != nil { return err }
	yv := v.cue.BuildFile(f)
	if err := yv.Err(); err != nil { return err }
	err = v.v.Unify(yv).Validate(cue.All(), cue.Concrete(true))
	var errs []error
	for _, e := range cueerrors.Errors(err) {
		loc := Location{File:file}
		if pos := cueerrors.Positions(e); len(pos) > 0 { loc.Line, loc.Column = pos[len(pos)-1].Line(), pos[len(pos)-1].Column() }
		errs = append(errs, Error{Message:e.Error(), Location:loc})
	}
	if len(errs) > 0 { return errorsGroup(errs) }

	// CUE checks the document shape. Resolve rule references against the declarations
	// in the same file, retaining YAML node positions for useful diagnostics.
	var doc struct {
		Namespace string `yaml:"namespace"`
		Flags []struct {
			Key string `yaml:"key"`
			Variants []struct { Key string `yaml:"key"` } `yaml:"variants"`
			Rules []struct {
				Segment yaml.Node `yaml:"segment"`
				Distributions []struct { Variant string `yaml:"variant"`; Node yaml.Node `yaml:"-"` } `yaml:"distributions"`
			} `yaml:"rules"`
		} `yaml:"flags"`
		Segments []struct { Key string `yaml:"key"` } `yaml:"segments"`
	}
	var root yaml.Node
	if err := yaml.Unmarshal(b, &root); err != nil { return err }
	if err := root.Decode(&doc); err != nil { return err }
	segments := map[string]bool{}
	for _, s := range doc.Segments { segments[s.Key] = true }
	for fi, flag := range doc.Flags {
		variants := map[string]bool{}
		for _, variant := range flag.Variants { variants[variant.Key] = true }
		for ri, rule := range flag.Rules {
			pos := nodeForRule(root.Content, fi, ri)
			if rule.Segment.Kind == yaml.ScalarNode {
				if !segments[rule.Segment.Value] { errs = append(errs, located(fmt.Sprintf("flag %s/%s rule %d references unknown segment %q", doc.Namespace, flag.Key, ri, rule.Segment.Value), file, rule.Segment.Line, rule.Segment.Column)) }
			} else if rule.Segment.Kind == yaml.MappingNode {
				for i:=0; i+1<len(rule.Segment.Content); i+=2 {
					if rule.Segment.Content[i].Value == "keys" { for _, key := range rule.Segment.Content[i+1].Content { if !segments[key.Value] { errs=append(errs,located(fmt.Sprintf("flag %s/%s rule %d references unknown segment %q",doc.Namespace,flag.Key,ri,key.Value),file,key.Line,key.Column)) } } }
				}
			}
			_ = pos
			for _, d := range rule.Distributions { if !variants[d.Variant] { errs=append(errs,located(fmt.Sprintf("flag %s/%s rule %d references unknown variant %q",doc.Namespace,flag.Key,ri,d.Variant),file,0,0)) } }
		}
	}
	if len(errs)>0 { return errorsGroup(errs) }
	return nil
}

func located(message, file string, line, column int) error { return Error{Message:message, Location:Location{File:file,Line:line,Column:column}} }
func nodeForRule(_ []*yaml.Node, _, _ int) *yaml.Node { return nil }

