}

// SnapshotFromPaths builds a snapshot from explicitly named files.
func SnapshotFromPaths(source fs.FS, paths ...string) (*StoreSnapshot, error) {
	var readers []io.Reader
	validator, err := cue.NewFeaturesValidator()
	if err != nil {
		return nil, err
	}
	for _, path := range paths {
		f, err := source.Open(path)
		if err != nil {
			return nil, err
		}
		b, err := io.ReadAll(f)
		f.Close()
		if err != nil {
			return nil, err
		}
		readers = append(readers, bytes.NewReader(b))
	}
	return snapshotFromNamedReaders(paths, readers...)
}

func snapshotFromFS(logger *zap.Logger, source fs.FS) (*StoreSnapshot, error) {
	return SnapshotFromFS(logger, source)
}

func snapshotFromNamedReaders(paths []string, readers ...io.Reader) (*StoreSnapshot, error) {
	validator, err := cue.NewFeaturesValidator()
	if err != nil { return nil, err }
	var copies []io.Reader
	for i, reader := range readers {
		b, err := io.ReadAll(reader); if err != nil { return nil, err }
		name := fmt.Sprintf("file-%d", i); if i < len(paths) { name = paths[i] }
		if err := validator.Validate(name, b); err != nil { return nil, err }
		copies = append(copies, bytes.NewReader(b))
	}
	return snapshotFromReaders(copies...)
}

